;------------------------------------------------------------------------------
; $82EC - Called from 82BE, 82C3, 82C7, 82CB, 82CF
; Arguments: X-REG=Address BASIC Table pointed to. Y-REG Token
; Outputs: Calculates offset into Command Vector Table at $8331 based on LB address given in BASIC Table.
; A few commands alter the value in XL before reacing here. For some functions, low ROM banked back in.
; Function jumped to be setting its address in P. Table of calcualted vectors below.
; RegMod: U, A, X
;
; Addr low byte > D7 indicates a Low Bank command
;                           Mofified
; Command     Token   Addr  Address    ; PTR   VECT   Bank
; "BREAK"     F0B3    CD89             ; Ignore has a real address
; "CLOAD"     F089    82EC             ; 8339 (901B)  Low
; "CSAVE"     F095    82DD             ; 8357 (901A)  Low
; "COM$"      E858    82D3             ; 836B (8893)  High
; "CONSOLE"   F0B1    82DE             ; 8355 (8365)  Low
; "DEV$"      E857    82D4             ; 8369 (8899)  High
; "DTE"       E884    82D1             ; 836F (8C8E)  High
; "ERN"       F052    82DF             ; 8353 (8312)  Low
; "ERL"       F053    82E0             ; 8351 (8309)  Low
; "FEED"      F0B0    82E1             ; 834F (9820)  Low
; "INPUT"     F091    82E2             ; 834D (8FFF)  Low
; "INSTAT"    E859    82E3             ; 834B (832A)  Low
; "LPRINT"    F0B9    82E4             ; 8349 (9056)  Low
; "LLIST"     F0B8    82E5             ; 8347 (901D)  Low
; "MERGE"     F08F    82C0  (82F0)     ; 8331 (901C)  Low
; "OUTSTAT"   E880    82E6             ; 8345 (8334)  Low
; "PRINT"     F097    82E7             ; 8343 (900D)  Low
; "PROTOCOL"  E881    82E8             ; 8341 (8317)  Low
; "RINKEY$"   E85A    82E9             ; 833F (8357)  Low
; "SETCOM"    E882    82D6             ; 8365 (8907)  High
; "SETDEV"    E886    82D5             ; 8367 (8968)  High
; "SPACE$"    F061    82EA             ; 833D (83D8)  Low
; "TERMINAL"  E883    82D2             ; 836D (8C88)  High
; "TRANSMIT"  E885    82D7             ; 8363 (89F5)  High
; "TAB"       F0BB    880D             ; Ignore has a real address
; "ZONE"      F0B4    82EB             ; 843D (83D8)  Low
; "INPUT#"    NNNN    82CE  (82ED)     ; 8337 (9660)  Low
; "PRINT#"    NNNN    82C9  (82EE)     ; 8335 (93D0)  Low
; "PRINT#2"   NNNN    82CD  (82EF)     ; 8333 (93D4)  Low (for LPT)
; "INIT"      NNNN    82B8  (82D0)     ; 8371 (880A)  High, only one that does INC UL
;------------------------------------------------------------------------------
MAIN_ENTRY:
	ori (OUTSTAT_REG),0x08          ; 82EC  eb785008     Set Bit_3 = (D)CD (opposite of low bank)
HB_JMP_FRM_LB:
	ori (CRLF_REG),0x08             ; 82F0  eb785508     Entry from low bank, set Bit3 in CRLF_REGas High Bank flag
	sie                             ; 82F4  fd81         Enable interrupts
	psh x                           ; 82F6  fd88         X-REG=Address BASIC Table pointed to
	sjp PORTS_UPDATE                ; 82F8  be8a2a       Call sub(s) that configure CE-158 ***Is U used here?
	pop u                           ; 82FB  fd2a         Original X now in U
	ldi uh,0x83                     ; 82FD  6883         Setting up pointer, UL is original XL in table above
	sec                             ; 82FF  fb           Set Carry flag, for SBC below
	ldi a,0xD7                      ; 8300  b5d7         Used to calculate offset into vector table
	sbc ul                          ; 8302  20           A = A - UL.
BRANCH_8303:
	ldi ul,0x63                     ; 8303  6a63         U = 8363
	bcs BRANCH_830F                 ; 8305  8308         If UL <= D7, High Bank command, skip ahead.
	dec uh                          ; 8307  fd62         DEC UH 83 -> 82, U = 8263
	rie                             ; 8309  fdbe         Disable interrupts
	ani (CRLF_REG),0xF7             ; 830B  e97855f7     (CRLF_REG) = (CRLF_REG) & F7. Clear Bit 3 Used as flag to swtich back to Low Bank
BRANCH_830F:
	shl                             ; 830F  d9           A << 1: Before: A = INIT=07, A = INIT=A0
	adr u                           ; 8310  fdea         U = U + A. U-REG is pointer into vector table
	lin u                           ; 8312  65           A = (U) then INC U. Reading from Command Vector Table below
	sta xh                          ; 8313  08           XH = A. i.e. INIT A=88
	lda (u)                         ; 8314  25           A = (U). i.e. INIT A=0A
	sta xl                          ; 8315  0a           X-REG now has address of function
	bii (CRLF_REG),0x08             ; 8316  ed785508     Test Bit3 This bit cleared in 830B above to signal Low Bank function
	bzs BRANCH_831E                 ; 831A  8b02         If Bit 3 not set, we dropped through to 8307 so skip ahead to go back to Low Bank.
	stx p                           ; 831C  fd5e         P = X, Sets prg Cntr to jump to High Bank function ***JMP
BRANCH_831E:
	ldi uh,>ARW                     ; 831E  687a         U = $7A28 =  AR-W
	ldi ul,<ARW                     ; 8320  6a28
	ldi a,0xE3                      ; 8322  b5e3         Intialize $7A28-$7A31 to:
	sin u                           ; 8324  61           $E3  $BA  $83 $05, which is
	ldi a,0xBA                      ; 8325  b5ba         RPU
	sin u                           ; 8327  61           JMP  $8305
	ldi a,>LB_RTN_FRM_HB            ; 8328  b583         This code segent sets PU to
	sin u                           ; 832A  61           bank in lower half of the CE-158 ROM
	ldi a,<LB_RTN_FRM_HB            ; 832B  b505
	sta (u)                         ; 832D  2e
	jmp ARW                         ; 832E  ba7a28       Jumps to $7A28, runs code segment POKED in above



