; $8380 - JMP_8380
; Jumped to from SUB_8D04:8E52 with UL = $02
;   jumps back to SUB_8D04:8E55
; If CRLF_REG Bit7 set OR Japanese market OR DATA_PTR_H > 0 OR 7 Data Bits then UL = $02. Else UL = 0A
;
; Arguments: UL
; Output: UL/A = 02 or 0A
; RegMod: A, UL
;------------------------------------------------------------------------------
JMP_8380:
	bii (CRLF_REG),0x80             ; 8380  ed785580     Not sure what this register does
	bzs BRANCH_839D                 ; 8384  8b17         If Bit 7 was set
	bii #(PC1500_PRT_B),0x08        ; 8386  fdedf00f08   Test Bit3. Japanese/Export jumper.
	bzr BRANCH_839D                 ; 838B  8910         If PC-1500 Export model. (Vcc export, Gnd Japanese)
	lda (DATA_PTR_H)                ; 838D  a578be       Normally used for DATA statement pointer
	bzr BRANCH_839D                 ; 8390  890b         If A > 0 branch fwd
	lda (SETCOM_REG)                ; 8392  a57858       Bits 3,4 are Word Length
	ani a,0x18                      ; 8395  b918         Keep Bits 3-4
	cpi a,0x10                      ; 8397  b710         Only Bit 4 set = 7 data bits
	bzr BRANCH_839D                 ; 8399  8902         If A != 10, i.e. 7 data bits, branch fwd
	ldi ul,0x0A                     ; 839B  6a0a         If 7 Data Bits
BRANCH_839D:
	lda ul                          ; 839D  24           Jump directly here if PC-1500 export model
	sta (BRK_TOP_H)                 ; 839E  ae78b0       Beginning of program containing BREAK line
	jmp JMP_8E55                    ; 83A1  ba8e55       Jumping back into SUB_8D04



