;------------------------------------------------------------------------------
; $86F0 - ***JMP
; Calculates a new address to set P to (Program Counter) and it is POKED into P.
; Part of Terminal program
; Arguments: A
; Output:
; RegMod: U, A, X
;------------------------------------------------------------------------------
SUB_86F0:
	lda (ERR_TOP_H)                 ; 86F0  a578b6       Being used as a place to pass values to functions 8BD4 A >= $0A and A <= $2E, $8F7C A >= $0A and A <= $15
	sec                             ; 86F3  fb           Set Carry Flag To subtract set carry. If carry is cleared it indicates a borrow
	sbi a,0x0A                      ; 86F4  b10a         A = A - 0A
SUB_86F0_ALT_E1:
	shr                             ; 86F6  d5           A = A > 1. Through Carry, 0 into LSB A /= 2
	pop u                           ; 86F7  fd2a         Pops return address off of stack: $8BD7, $8F7F, $8ABC $8BD7 table $01+$12 bytes, $8F7F $01+$06 bytes, $8ABC table $01+$05 bytes
	psh a                           ; 86F9  fdc8         Save A.
	lin u                           ; 86FB  65           A = (U), then INC U. A = (8BD7) or A = (8F7F) or A = (8ABC) A = 12     or A = 06     or A =  05
	ldx u                           ; 86FC  fd28         X = 8BD8 or X = 8F80 or X = 8ABD
	adr u                           ; 86FE  fdea         U = U + A. U = 8BD8 + 12 = 8BEA or U = 8F80 + 06 = 8F86 or U = 8ABD + 05 = 8AC2, All three look like valid addresses
BRANCH_8700:
	pop a                           ; 8700  fd8a         Get original A back (12, 6, 5)
	psh u                           ; 8702  fda8         Save U. Return address?
	adr x                           ; 8704  fdca         X = $8BD8 + $00~$12 -> X = $8BD8~$8BEA X = $8F80 + $00~$05 -> X = $8F80~$8F85 X = $8ABD + $00~$04 -> X = $8ABD~$8AC1
	lin x                           ; 8706  45           A = (X), X = X + 1 A = ($8BD8~$8BEA) = 1C 1E 1B 18 1A 1B 67  6B 90 7D 9A 2D 3C 3B 3A  39 38 2D A = ($8F80~$8F85) = 21 24 27 16 19 10 A = ($8ABD~$8AC1) = 05 10 42 5E 4F
	adr x                           ; 8707  fdca         X = X + A (+ 1 from above LIN) - $8BD9+$1C=$8BF5, $8BDA+$1E=$8BF8, $8BDB+$1B=$8BF6, $8BDC+$18=$8BF4, $8BDD+$1A=$8BF7 $8BDE+$1B=$8BF9, $8BDF+$67=$8C46, $8BE0+$6B=$8C4B, $8BE1+$90=$8C71, $8BE2+$7D=$8C5F $8BE3+$9A=$8C7D, $8BE4+$2D=$8C11, $8BE5+$3C=$8C21, $8BE6+$3B=$8C21, $8BE7+$3A=$8C21 $8BE8+$39=$8C21, $8BE9+$38=$8C21, $8BEA+$2D=$8C17 - $8F81+$21=$8FA2, $8F82+$24=$8FA6, $8F83+$27=$8FAA, $8F84+$16=$8F9A, $8F85+$19=$8F9E $8F86+$10=$8F96 - $8ABE+$05=$8AC3, $8ABF+$10=$8ACF, $8AC0+$42=$8B02, $8AC1+$5E=$8B1F, $8AC2+$4F=$8B11
	stx p                           ; 8709  fd5e         P = X. Set Program Counter to X ***JMP



;------------------------------------------------------------------------------
; $870B - Called from 873A
; Copies text string from TEXT_84EF (Terminal menu text) to Input Buffer (7BB0)
; Arguments: A = multiple of 2, string index
; Outputs:
; RegMod: A, X, Y, U
;------------------------------------------------------------------------------
TERMTXT_2INBUF:
	ldi yl,<IN_BUF                  ; 870B  5ab0         (Y)=7BB0, INPUT BUFFER Byte 0 START
	ldi yh,>IN_BUF                  ; 870D  587b         Setting up pointer?
	ldi xl,<TBL_84B0                ; 870F  4ab0         (X)=84B0, inside text @ TEXT_84EF
	ldi xh,>TBL_84B0                ; 8711  4884         Setting up pointer?
	cpi a,0x22                      ; 8713  b722         A is index into text table.
	bcr BRANCH_8723                 ; 8715  810c         Branch fwd if A < 22
	cpi a,0x2E                      ; 8717  b72e
	bcs BRANCH_8721                 ; 8719  8306         Branch fwd if A >= 2E
	ldi xl,0xFA                     ; 871B  4afa         X = 84FA ( A >= 22 and A < 2E )
	ldi ul,0x06                     ; 871D  6a06         U = loop counter, 7 bytes to copy
	bch BRANCH_8732                 ; 871F  8e11         Branch fwd unconditional
BRANCH_8721:
	sbi a,0x0C                      ; 8721  b10c         A = A - 0C, A = 22~??
BRANCH_8723:
	adr x                           ; 8723  fdca         X = 84B0 to 85A3? A = 0~F3.  A must be an even number.  If A = 0.
	shr                             ; 8725  d5           A = A >> 1.                           A = A / 2.
	adr x                           ; 8726  fdca         X= X + A.                             X = 84B0 + 0 = 84B0.
	lin x                           ; 8728  45           A = (X) then INC X.                   A = (84B0) = 19
	sta ul                          ; 8729  2a           UL = 19. Copy 20 bytes
	lin x                           ; 872A  45           A = (X) then INC X.                   A = (84B1) = 85
	psh a                           ; 872B  fdc8         Save A
	lda (x)                         ; 872D  05           A = (X).                              A = (84B2) = 7F.
	sta xl                          ; 872E  0a           X = 7F
	pop a                           ; 872F  fd8a         A = 85
	sta xh                          ; 8731  08           X = 857F
BRANCH_8732:
	tin                             ; 8732  f5           (Y) = (X) then X = X + 1, Y = Y + 1
	lop ul,BRANCH_8732              ; 8733  8803         UL = UL - 1, loop back 'e' if Borrow Flag not set
	rtn                             ; 8735  9a



