; $87DE - NULL2COM
; Sends a 00 (NULL) to RS232 if SETDEV_REG Bit 6 is set.
; Arguments:
; Output:
; RegMod: UL, A
;------------------------------------------------------------------------------
NULL2COM:
	bii (SETDEV_REG),0x40           ; 87DE  ed785740     Test Bit 6 in SETDEV_REG. Bit 6 for CO? KI = 01, DO = 02, PO = 04, CI = 08, CO = 10
	bzs BRANCH_87F1                 ; 87E2  8b0d         Branch fwd if Bit 6 not set. Is Bit 6 a retry flag? Bits 6-7 set on power on reset. Bit 7 might be THRE?
	ldi ul,0x0F                     ; 87E4  6a0f         Try counter
	rie                             ; 87E6  fdbe         Disable interrupts
BRANCH_87E8:
	ldi a,0x00                      ; 87E8  b500         Charecter to send
	sjp CHAR2COM                    ; 87EA  be81bc       Sends charecter in A to RS232 Port
	bcr BRANCH_87F1                 ; 87ED  8102         Branch fwd if Carry reset, Carry reset = success
	lop ul,BRANCH_87E8              ; 87EF  8809         UL = UL - 1, loop back 'e' if Borrow Flag not set
BRANCH_87F1:
	sie                             ; 87F1  fd81         Enable Interrupts
	rtn                             ; 87F3  9a



