;------------------------------------------------------------------------------
; $8899 - DEV$ - Called from Command Vector Table at $8331
; Converts SETDEV and SETCOM settings into ASCII
; Then it POKES in either 'RPU, RTN' or just 'RTN' to 7A30 and calls it.
; Arguments:
; Output:
; RegMod: Y, U, A
;------------------------------------------------------------------------------
DEV_STR:
	ori (STK_PTR_GSB_FOR),0xFF      ; 8899  eb7882ff     $00 = COM$, $FF= DEV$
BRANCH_889D:
	ldi yl,0x2E                     ; 889D  5a2e         Set up pointer?
	ldi yh,0x7A                     ; 889F  587a         Y = 7A2E -> in AR-W
	ldi ul,0x15                     ; 88A1  6a15         Loop counter, 15-0 16 bytes copied
	ldi a,0x2C                      ; 88A3  b52c         Value to be poked in $2C ','
BRANCH_88A5:
	sde y                           ; 88A5  53           (Y) = A. Then DEC Y. Y=7A2E~7A18, fill with 2C ','
	lop ul,BRANCH_88A5              ; 88A6  8803         DEC UL, if borrow flag not set loop back
	lda (STK_PTR_GSB_FOR)           ; 88A8  a57882       (STK_PTR_GSB_FOR) = $00 COM$ or $FF DEV$. Y = 7A18
	bzr BRANCH_88BE                 ; 88AB  8911         [5] If A != 0 branch fwd. If mode is COM$ or UR$
	sjp SETCOM2ASCII                ; 88AD  be8c4b       COM$. Converts Baud Rate setting in SETCOM to ASCII?
	inc y                           ; 88B0  54           Y = 7A19. Leaving a ',' between
	sjp WORDLEN2ASCII               ; 88B1  be8c71       Updates (Y) with ASCII value for Word Length, Y = 7A1A
	inc y                           ; 88B4  54           Y = 7A1B. Leaving a ',' between
	sjp PARITY2ASCII                ; 88B5  be8c5f       Updates (Y) with ASCII charecter for Parity, Y = 7A1C
	inc y                           ; 88B8  54           Y = 7A1D. Leaving a ',' between
	sjp STOPBIT2ASCII               ; 88B9  be8c7d       Updates (Y) with ASCII charecter for #Stop Bits Y = 7A1E
	bch BRANCH_88E3                 ; 88BC  8e25         Branch fwd to display section
BRANCH_88BE:
	lda (SETDEV_REG)                ; 88BE  a57857       (3) Which devices are redirected to RS232 KI = 01, DO = 02, PO = 04, CI = 08, CO = 10
	sta ul                          ; 88C1  2a           (2) UL = A = SETDEV_REG
	lda (OPN_TBL)                   ; 88C2  a579d1       (3) OPN device code, Basic table to search first
	cpi a,0xC0                      ; 88C5  b7c0         (2) Is OPN set to CE-158?
	bzs BRANCH_88CB                 ; 88C7  8b02         (2) If A == C0 branch fwd
	ldi ul,0x00                     ; 88C9  6a00         (2) [11] If OPN != CE-158 zero what was read from SETDEV_REG
BRANCH_88CB:
	lda ul                          ; 88CB  24           (1) A = UL = (SETDEV_REG) or $00 is OPN != $0C (OPN_TBL)
	ldi xl,<TBL_SETDEV_TEXT         ; 88CC  4ad8         (2) X = 83D8. SETDEV Command text table
	ldi xh,>TBL_SETDEV_TEXT         ; 88CE  4883         (2) Y = 7A1E
	ldi ul,0x04                     ; 88D0  6a04         (2) [7] Loop counter, 4-0 all 5 possible SETDEV settings
BRANCH_88D2:
	tin                             ; 88D2  f5           (Y) = (X) then INC both X,Y. X = 83D9, Y = 7A1F
	tin                             ; 88D3  f5           (Y) = (X) then INC both X,Y. X = 83DA, Y = 7A20
	inc y                           ; 88D4  54           Y = Y + 1 = 7A21, leaving a ','
	shr                             ; 88D5  d5           A = A >> 1. A = (SETDEV_REG) or $00
	bcs BRANCH_88DB                 ; 88D6  8303         If Bit 0 (KI?) was set branch fwd
	dec y                           ; 88D8  56           Y = 7A1F
	dec y                           ; 88D9  56           Y - 7A1E
	dec y                           ; 88DA  56           Y = 7A1D
BRANCH_88DB:
	inc x                           ; 88DB  44           X = 83DB, next text entry (DO)
	lop ul,BRANCH_88D2              ; 88DC  880c         UL = UL - 1, loop back 'e' if Borrow Flag not set.
	cpi yl,0x19                     ; 88DE  5e19         Y=7A19?
	bcr BRANCH_88E3                 ; 88E0  8101         If YL < 19 branch fwd
	dec y                           ; 88E2  56
BRANCH_88E3:
	lda yl                          ; 88E3  14
	sec                             ; 88E4  fb           Set Carry
	ldi xl,<ARU                     ; 88E5  4a18
	sbc xl                          ; 88E7  00           A = A - XL, A is string length?
	ldi xh,>ARU                     ; 88E8  487a         X = 7A18
	sjp XREG2STRBUF                 ; 88EA  bedfa1       X points to string to insert into String buffer. Branch if overflow
	.db BRANCH_88F0-.-1             ; 88ED  02
	ldi uh,0x00                     ; 88EE  6800
BRANCH_88F0:
	ldi a,0x9A                      ; 88F0  b59a
	bii (OUTSTAT_REG),0x80          ; 88F2  ed785080     No idea what Bit7 is
	bzr BRANCH_8901                 ; 88F6  8909         If Bit 7 is set branch fwd, to poke RTN, 9A into 7A30
	sta (0x7A31)                    ; 88F8  ae7a31       or into 7A31
	ani (CRLF_REG),0xF7             ; 88FB  e97855f7     Clear Bit 3. Flag for?
	ldi a,0xE3                      ; 88FF  b5e3         RPU opcode
BRANCH_8901:
	sta (ARS)                       ; 8901  ae7a30       If branched here are are poking 9A RTN, else E3 SPU, 9A RTN (to swtich to low bank)
	jmp ARS                         ; 8904  ba7a30       Were are doing RTN to what?



