;------------------------------------------------------------------------------
; $89CB - copies text from constant or string variable to the String buffer
; Arguments: (8968) X=$8068, Y=token, (8907) X=$8097, Y=token
; Output: Text into String Buffer, 0D delimited. C=0 if string not found.
; RegMod: A,X,Y
;------------------------------------------------------------------------------
TXT2STRBUF:
	vmj 0x36                        ; 89CB  cd36         Stores CSI of text constant or text variable in AR-X (C=1). If no string is detected, C=0
	ani (TRACE),0x00                ; 89CD  e9788e00     Clear all bits, flag for no string?
	bcr BRANCH_89EE                 ; 89D1  811b         Carry reset - No string
	psh y                           ; 89D3  fd98         Save Y. Y-REG is token of calling function
	ori (TRACE),0xFF                ; 89D5  eb788eff     Set all bits, flag for string?
	vej 0xDC                        ; 89D9  dc           Loads CSI from AR-X: (X) Address, UL & A length.
	ldi yl,<STR_BUF                 ; 89DA  5a10         CSI = 'Character String Information'
	ldi yh,>STR_BUF                 ; 89DC  587b         $7B10 - STRING BUFFER Byte 0 Start
	bzs BRANCH_89E5                 ; 89DE  8b05         Skip if length in UL is zero
	dec a                           ; 89E0  df           A = A - 1. A is string length.
	sta ul                          ; 89E1  2a           Loop counter
BRANCH_89E2:
	tin                             ; 89E2  f5           (Y) = (X) then X = X + 1, Y = Y + 1
	lop ul,BRANCH_89E2              ; 89E3  8803         UL = UL - 1, loop back 'e' if Borrow Flag not set
BRANCH_89E5:
	ldi a,0x0D                      ; 89E5  b50d         0D = CR
	sta (y)                         ; 89E7  1e           (Y) = A, add CR to end of string
	ldi yl,0x10                     ; 89E8  5a10         Set Y back to start of buffer
	pop x                           ; 89EA  fd0a         X=token of calling function?
	sec                             ; 89EC  fb           Set Carry Flag
	rtn                             ; 89ED  9a           Return
BRANCH_89EE:
	stx y                           ; 89EE  fd5a         Y = X. Y-REG is address of calling function.
	rtn                             ; 89F0  9a           Return



