	aex                             ; 8B09  f1           Swap hi and low nibbles of A. If A = 08 then A = 80
	shr                             ; 8B0A  d5           A = A >> 1. A = 80 >> = 40
	ani (SETCOM_REG),0xE7           ; 8B0B  e97858e7     Bits 0,1 Parity. Bit 2 Stop Bit. Bits 3,4 Word Length. Bits 5,6,7 Baud.
	bch BRANCH_8B37                 ; 8B0F  8e26         Unconditional branch fwd. Argument in A
PARSE_STOPBITS:
