	.db 0x31                        ; 8B13  31           check whether value in UL in interval n1-n2. If not branch n3
	.db 0x33                        ; 8B14  33           $31-$33: 1,2,3 i.e. Stop Bits
	.db BRANCH_8B2B-.-1             ; 8B15  15
