	shl                             ; 8B18  d9           A = A << 1. Shifted through Carry, 0 into LSB
	ani (SETCOM_REG),0xFB           ; 8B19  e97858fb     clear Bit 2, Stop Bit. Bits 3,4 cleared above. Bits 0,1 Parity. Bit 2 Stop Bit. Bits 3,4 Word Length. Bits 5,6,7 Baud.
